document.addEventListener("DOMContentLoaded",()=>{if("undefined"==typeof Swiper)return;const e=document.querySelectorAll(".swiper");if(e.length)for(const t of e){const e=t.querySelector(".swiper-pagination"),o=t.querySelector(".swiper-button-next"),n=t.querySelector(".swiper-button-prev"),i=t.querySelector(".swiper-scrollbar"),r=t.classList.contains("swiper--autoheight");new Swiper(t,{direction:"horizontal",loop:!0,autoHeight:r,pagination:e?{el:e,clickable:!0}:void 0,navigation:o&&n?{nextEl:o,prevEl:n}:void 0,scrollbar:i?{el:i,draggable:!0}:void 0,on:r?{init(e){const o=t.querySelectorAll("img");for(const t of o){const o=()=>e.updateAutoHeight(0);t.complete?"function"==typeof t.decode?t.decode().then(o).catch(o):o():(t.addEventListener("load",o,{once:!0}),t.addEventListener("error",o,{once:!0}))}e.updateAutoHeight(0)},slideChangeTransitionEnd(e){e.updateAutoHeight(300)}}:void 0})}});